    "sum": "家庭教育从「家事」上升为「国事」：家长失职可被训诫、责令接受家庭教育指导——法律的立场是「帮家长」而非「罚家长」。",
    "body": "核心条款：父母承担家庭教育主体责任；学校/社区可提供指导；涉及未成年人权益受侵害时公权可介入。",
